// Check if any signals were delivered or blocked
const result = $json;
const total = result.total_generated || 0;
const delivered = result.delivered || 0;
const blocked = result.blocked || 0;
const signals = result.signals || [];

let summary = `📊 3Commas Signal Report\n`;
signals.forEach(s => {
  const gate = s.gates || {};
  const status = gate.delivery || gate.suppress_short || gate.rate_limit || gate.confidence || 'unknown';
  summary += `${s.action} ${s.instrument}: ${status}\n`;
});

if (blocked > 0) {
  summary += `\n🚫 ${blocked} signal(s) blocked by SUPPRESS_SHORT`;
}

return [{
  json: {
    timestamp: new Date().toISOString(),
    total,
    delivered,
    blocked,
    signals,
    summary,
    is_alert: delivered > 0 || blocked > 0
  }
}];
